func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestAddWithNegativeNumbers(t *testing.T) {
	tests := []struct {
		name string
		a    int
		b    int
		want int
	}{
		{name: "negative first operand", a: -2, b: 3, want: 1},
		{name: "negative second operand", a: 5, b: -3, want: 2},
		{name: "both negative", a: -4, b: -6, want: -10},
		{name: "larger negative magnitude", a: -10, b: 3, want: -7},
		{name: "negative zero", a: 0, b: -7, want: -7},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := add(tt.a, tt.b); got != tt.want {
				t.Fatalf("add(%d, %d) = %d, want %d", tt.a, tt.b, got, tt.want)
			}
		})
	}
}

